# -*- coding: utf-8 -*-
"""YOUBIN SAMIUL single-file launcher for Render and Railway.

The application modules and dashboard HTML are embedded in this file and are
atomically extracted next to app.py at startup. Runtime dependencies belong in
requirements.txt. Configure PORT automatically on Render/Railway, and use
ACCOUNTS_FILE to point account storage at a persistent volume when available.
"""
import base64
import importlib.util
import json
import os
from pathlib import Path
import runpy
import subprocess
import sys
import zlib

BUNDLED_FILES = json.loads(r'{"main.py":"","dashboard_server.py":"","CguTeam_pb2.py":"","CguFF_pb2.py":"","thunderFF_pb2.py":"","StartMatch_pb2.py":"","message_ids.py":"","templates/index.html":"","templates/auth.html":"","templates/landing.html":""}')

# import name -> pip package name
REQUIRED = {
    "aiohttp": "aiohttp",
    "httpx": "httpx",
    "requests": "requests",
    "Crypto": "pycryptodome",
    "google.protobuf": "protobuf",
    "google_play_scraper": "google-play-scraper",
    "protobuf_decoder": "protobuf-decoder",
}


def _has(module: str) -> bool:
    try:
        return importlib.util.find_spec(module) is not None
    except (ImportError, ValueError):
        return False


def _is_termux() -> bool:
    return "com.termux" in os.environ.get("PREFIX", "") or os.path.isdir("/data/data/com.termux")


def ensure_dependencies() -> None:
    missing = [pip for mod, pip in REQUIRED.items() if not _has(mod)]
    if not missing:
        return
    termux = _is_termux()
    print("\n[setup] Missing Python packages: " + ", ".join(missing))
    auto_flag = os.environ.get("AUTO_INSTALL")
    interactive = bool(sys.stdin) and sys.stdin.isatty()
    if auto_flag == "1" or (interactive and auto_flag != "0"):
        print("[setup] Installing them now (internet needed, this runs only once)...")
        env = dict(os.environ)
        if termux:   # avoid slow native builds on Android
            env.update(MULTIDICT_NO_EXTENSIONS="1", YARL_NO_EXTENSIONS="1", FROZENLIST_NO_EXTENSIONS="1")
        code = subprocess.call([sys.executable, "-m", "pip", "install", *missing], env=env)
        importlib.invalidate_caches()
        missing = [pip for mod, pip in REQUIRED.items() if not _has(mod)]
        if code == 0 and not missing:
            print("[setup] Done. Starting the app...\n")
            return
        print("[setup] Automatic install did not finish. Still missing: " + ", ".join(missing or ["(see pip errors above)"]))
    print("\nInstall them manually, then run the app again:\n")
    if termux:
        print("  pkg update -y && pkg install -y python clang libffi openssl binutils")
        print("  MULTIDICT_NO_EXTENSIONS=1 YARL_NO_EXTENSIONS=1 FROZENLIST_NO_EXTENSIONS=1 pip install aiohttp")
        print("  pip install " + " ".join(p for p in REQUIRED.values() if p != "aiohttp"))
    else:
        print("  pip install " + " ".join(REQUIRED.values()))
    print("\nNote: message_ids.py is NOT downloaded. It is built into app.py and extracted automatically.\n")
    sys.exit(1)


def resolve_app_dir() -> Path:
    root = Path(__file__).resolve().parent
    if os.access(root, os.W_OK):
        return root
    fallback = Path.home() / ".youbin_samiul_app"      # read-only folder (e.g. shared storage)
    fallback.mkdir(parents=True, exist_ok=True)
    print(f"[setup] {root} is not writable. Using {fallback} instead.")
    return fallback


ensure_dependencies()
ROOT = resolve_app_dir()

for relative_path, encoded_content in BUNDLED_FILES.items():
    destination = (ROOT / relative_path).resolve()
    # Only extract paths embedded by this build and keep them within the app root.
    if destination != ROOT and ROOT not in destination.parents:
        raise RuntimeError(f"Invalid embedded application path: {relative_path}")
    destination.parent.mkdir(parents=True, exist_ok=True)
    decoded = zlib.decompress(base64.b64decode(encoded_content))
    temporary = destination.with_name(destination.name + f".tmp-{os.getpid()}")
    try:
        temporary.write_bytes(decoded)
        os.replace(temporary, destination)
    finally:
        try:
            if temporary.exists():
                temporary.unlink()
        except OSError:
            pass

os.chdir(ROOT)
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))   # makes `import message_ids` etc. work from any folder
runpy.run_path(str(ROOT / "main.py"), run_name="__main__")
